import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
import io
import re
import numpy as np
from collections import Counter

# ─── Load & Clean Data ───────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

def extract_question_core(text):
    if pd.isna(text):
        return ''
    return str(text).split('$')[0].strip()

df['core_question'] = df['question'].apply(extract_question_core)

# ─── KPI Calculations ────────────────────────────────────────────────────────
total_questions = len(df)
year_range = sorted(df['year'].unique())
type_counts = df['type'].value_counts()
type_overall_pct = (type_counts / total_questions * 100).round(1)

yearly_totals = df.groupby('year').size().reset_index(name='total')
yearly_type = df.groupby(['year', 'type']).size().unstack(fill_value=0).reset_index()

for t in ['MCQs', 'Short', 'Long']:
    if t not in yearly_type.columns:
        yearly_type[t] = 0

yearly_type = yearly_type.merge(yearly_totals, on='year')

for t in ['MCQs', 'Short', 'Long']:
    yearly_type[f'{t}_pct'] = (yearly_type[t] / yearly_type['total'] * 100).round(1)

yearly_type = yearly_type.sort_values('year').reset_index(drop=True)
yearly_type['yoy_abs'] = yearly_type['total'].diff()
yearly_type['yoy_pct'] = (yearly_type['total'].pct_change() * 100).round(1)

avg_per_type = {t: round(df[df['type'] == t].groupby('year').size().mean(), 1) for t in ['MCQs', 'Short', 'Long']}

# ─── Topic / Keyword Analysis ────────────────────────────────────────────────
stop_words = {
    'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'shall',
    'should', 'may', 'might', 'must', 'can', 'could', 'of', 'in', 'to',
    'for', 'with', 'on', 'at', 'by', 'from', 'as', 'into', 'through',
    'during', 'before', 'after', 'above', 'below', 'between', 'out', 'off',
    'over', 'under', 'again', 'further', 'then', 'once', 'and', 'but',
    'or', 'nor', 'not', 'so', 'yet', 'both', 'either', 'neither', 'each',
    'every', 'all', 'any', 'few', 'more', 'most', 'other', 'some', 'such',
    'no', 'only', 'own', 'same', 'than', 'too', 'very', 'just', 'because',
    'if', 'when', 'where', 'how', 'what', 'which', 'who', 'whom', 'this',
    'that', 'these', 'those', 'it', 'its', 'he', 'she', 'they', 'them',
    'we', 'us', 'you', 'i', 'me', 'my', 'your', 'his', 'her', 'their',
    'our', 'also', 'about', 'up', 'down', 'here', 'there', 'while',
    'write', 'define', 'explain', 'differentiate', 'different', 'following',
    'given', 'example', 'program', 'statement', 'statements', 'number',
    'value', 'values', 'used', 'use', 'using', 'called', 'known',
    'following', 'name', 'two', 'three', 'four', 'one', 'any', 'type',
    'types', 'full', 'form', 'output', 'input', 'purpose', 'meaning',
    'difference', 'advantages', 'various', 'among', 'within',
    'int', 'float', 'char', 'void', 'double', 'main', 'print', 'printf',
    'scanf', 'include', 'define', 'return', 'case', 'break', 'else',
    'correct', 'wrong', 'equivalent', 'convert', 'rewrite', 'debug',
    'determine', 'identify', 'list', 'draw', 'step', 'steps',
    'valid', 'invalid', 'reason', 'calculate', 'find', 'check',
}

def tokenize(text):
    text = text.lower()
    text = re.sub(r'[^a-z\s]', ' ', text)
    tokens = text.split()
    return [t for t in tokens if t not in stop_words and len(t) > 2]

all_tokens = []
df['tokens'] = df['core_question'].apply(lambda x: all_tokens.extend(tokenize(x)))

keyword_freq = Counter(all_tokens)
top_keywords = keyword_freq.most_common(30)

# Topic clusters
topic_clusters = {
    'Loops & Iteration': ['loop', 'while', 'for', 'do', 'nested', 'iteration', 'iterate', 'continue'],
    'Functions & Recursion': ['function', 'recursive', 'recursion', 'prototype', 'parameter', 'argument', 'call', 'return'],
    'Database Fundamentals': ['database', 'dbms', 'rdbms', 'record', 'field', 'tuple', 'attribute', 'entity', 'schema', 'normalization', 'normal', 'redundancy', 'integrity'],
    'Database Keys & Relationships': ['primary', 'foreign', 'key', 'candidate', 'composite', 'super', 'relationship', 'relational', 'referential'],
    'Data Types & Variables': ['data', 'variable', 'constant', 'integer', 'string', 'character', 'byte', 'size', 'type', 'casting', 'storage'],
    'Operators': ['operator', 'arithmetic', 'logical', 'relational', 'assignment', 'bitwise', 'increment', 'decrement', 'precedence', 'ternary', 'unary'],
    'Control Structures': ['switch', 'if', 'else', 'nested', 'control', 'selection', 'decision', 'conditional', 'goto'],
    'I/O & Format Specifiers': ['format', 'specifier', 'printf', 'scanf', 'gets', 'input', 'output', 'escape', 'sequence'],
    'MS Access': ['access', 'table', 'query', 'form', 'report', 'object', 'macro', 'module'],
    'File Handling': ['file', 'fopen', 'fclose', 'fscanf', 'mode', 'open', 'handling'],
    'Arrays & Structures': ['array', 'structure', 'pointer', 'union'],
    'SQL & DDL/DML': ['sql', 'ddl', 'dml', 'dcl', 'tcl', 'query', 'language', 'definition', 'manipulation', 'control', 'transaction'],
}

topic_yearly = {}
