df = pd.read_csv('/app/benchmark/data.csv')

def extract_question_core(text):
    if pd.isna(text):
        return ''
    return str(text).split('$')[0].strip()

df['core_question'] = df['question'].apply(extract_question_core)

# ─── KPI Calculations ────────────────────────────────────────────────────────
total_questions = len(df)
year_range = sorted(df['year'].unique())
type_counts = df['type'].value_counts()
type_overall_pct = (type_counts / total_questions * 100).round(1)

yearly_totals = df.groupby('year').size().reset_index(name='total')
yearly_type = df.groupby(['year', 'type']).size().unstack(fill_value=0).reset_index()

for t in ['MCQs', 'Short', 'Long']:
    if t not in yearly_type.columns:
        yearly_type[t] = 0

yearly_type = yearly_type.merge(yearly_totals, on='year')

for t in ['MCQs', 'Short', 'Long']:
    yearly_type[f'{t}_pct'] = (yearly_type[t] / yearly_type['total'] * 100).round(1)

yearly_type = yearly_type.sort_values('year').reset_index(drop=True)
yearly_type['yoy_abs'] = yearly_type['total'].diff()
yearly_type['yoy_pct'] = (yearly_type['total'].pct_change() * 100).round(1)

avg_per_type = {t: round(df[df['type'] == t].groupby('year').size().mean(), 1) for t in ['MCQs', 'Short', 'Long']}

