def yearly_table_rows():
    rows = ''
    for _, r in yearly_type.iterrows():
        yoy_str = f'{int(r["yoy_abs"]):+d}' if pd.notna(r['yoy_abs']) and r['yoy_abs'] != 0 else '—'
        yoy_pct_str = f'{r["yoy_pct"]:+.1f}%' if pd.notna(r['yoy_pct']) else '—'
        rows += f'''<tr>
            <td>{int(r["year"])}</td>
            <td>{r["MCQs"]}</td>
            <td>{r["Short"]}</td>
            <td>{r["Long"]}</td>
            <td><strong>{r["total"]}</strong></td>
            <td>{r["MCQs_pct"]}%</td>
            <td>{r["Short_pct"]}%</td>
            <td>{r["Long_pct"]}%</td>
            <td>{yoy_str}</td>
            <td>{yoy_pct_str}</td>
        </tr>'''
    return rows

def topic_table_rows():
    rows = ''
    for topic in topic_labels:
        counts = [topic_yearly[topic].get(y, 0) for y in all_years_list]
        total = sum(counts)
        row_cells = ''.join(f'<td>{c}</td>' for c in counts)
        rows += f'<tr><td><strong>{topic}</strong></td>{row_cells}<td><strong>{total}</strong></td></tr>'
    return rows

def keyword_table_rows():
    rows = ''
    for kw, freq in top_keywords:
        rows += f'<tr><td>{kw}</td><td>{freq}</td></tr>'
    return rows

